    { q = "I am become Death, the destroyer of worlds.", a = "J. Robert Oppenheimer", b = "Quoting the Bhagavad Gita" },
    { q = "The release of atomic energy has not created a new problem. It has merely made more urgent the necessity of solving an existing one.", a = "Albert Einstein", b = "Atomic War or Peace (1945)" },
    { q = "He made an instrument to know / If the moon shine at full or no.", a = "Samuel Butler", b = "Hudibras" },
    { q = "Every particle of matter is attracted by or gravitates to every other particle of matter with a force inversely proportional to the squares of their distances.", a = "Isaac Newton", b = "Philosophiae Naturalis Principia Mathematica" },
    { q = "Everything passes – Robust art / Alone is eternal. / The bust / Survives the city.", a = "Théophile Gautier", b = "L'Art" },
    { q = "In nothing do men more nearly approach the gods than in giving health to men.", a = "Cicero", b = "Pro Ligario" },
    { q = "There is only one good, knowledge, and one evil, ignorance.", a = "Socrates", b = "Diogenes Laërtius, Lives of the Eminent Philosophers" },
    { q = "Measure what is measurable, and make measurable what is not so.", a = "Galileo Galilei", b = "Attributed" },
