    { q = "Vision is the art of seeing things invisible.", a = "Jonathan Swift", b = "Thoughts on Various Subjects" },
    { q = "The whole country was tied together by radio. We all experienced the same heroes and comedians and singers. They were giants.", a = "Woody Allen", b = "Interview" },
    { q = "The introduction of so powerful an agent as steam to a carriage on wheels will make a great change in the situation of man.", a = "Thomas Jefferson", b = "Letter to Charles Willson Peale (1802)" },
    { q = "And homeless near a thousand homes I stood, and near a thousand tables pined and wanted food.", a = "William Wordsworth", b = "Guilt and Sorrow" },
    { q = "Nothing is particularly hard if you divide it into small jobs.", a = "Henry Ford", b = "My Life and Work" },
    { q = "It is well that war is so terrible, or we should grow too fond of it.", a = "Robert E. Lee", b = "Remark at the Battle of Fredericksburg (1862)" },
    { q = "1. A robot may not injure a human being or, through inaction, allow a human being to come to harm. 2. A robot must obey any orders given to it by human beings, except when such orders would conflict with the First Law. 3. A robot must protect its own existence as long as such protection does not conflict with the First or Second Law.", a = "Isaac Asimov", b = "Runaround (Three Laws of Robotics)" },
    { q = "A good rule for rocket experimenters to follow is this: always assume that it will explode.", a = "Astronautics Magazine", b = "1937 Issue" },
    { q = "He who commands the sea has command of everything.", a = "Themistocles", b = "Plutarch's Lives" },
    { q = "Now, somehow, in some new way, the sky seemed almost alien.", a = "Lyndon B. Johnson", b = "Remarks on Sputnik (1957)" },
    { q = "Every great advance in science has issued from a new audacity of imagination.", a = "John Dewey", b = "The Quest for Certainty" },
    { q = "Be extremely subtle, even to the point of formlessness. Be extremely mysterious, even to the point of soundlessness. Thereby you can be the director of the opponent’s fate.", a = "Sun Tzu", b = "The Art of War" },
    { q = "The nations of the West hope that by means of steam communication all the world will become as one family.", a = "Townsend Harris", b = "Journal (1856)" },
    { q = "John Henry said to his Captain, 'A man ain’t nothin’ but a man, And before I’ll let your steam drill beat me down, I’ll die with the hammer in my hand.'", a = "Anonymous", b = "The Ballad of John Henry, the Steel-Drivin’ Man" },
    { q = "I once sent a dozen of my friends a telegram saying ‘flee at once – all is discovered.’ They all left town immediately.", a = "Mark Twain", b = "Attributed" },
    { q = "Wisdom and virtue are like the two wheels of a cart.", a = "Japanese Proverb", b = "Traditional Saying" },
    { q = "Three things are necessary for the salvation of man: to know what he ought to believe; to know what he ought to desire; and to know what he ought to do.", a = "St. Thomas Aquinas", b = "Two Precepts of Charity" },
    { q = "Even brute beasts and wandering birds do not fall into the same traps or nets twice.", a = "Saint Jerome", b = "Letters" },
    { q = "He who destroys a good book kills reason itself.", a = "John Milton", b = "Areopagitica" },
    { q = "The temple is like no other building in the world. It has towers and decoration and all the refinements which the human genius can conceive of.", a = "António da Madalena", b = "Travel Accounts (1586)" },
    { q = "To achieve great things, two things are needed: a plan, and not quite enough time.", a = "Leonard Bernstein", b = "Address to the National Press Club (1980)" },
    { q = "Pale Death beats equally at the poor man’s gate and at the palaces of kings.", a = "Horace", b = "Odes" },
    { q = "The katun is established at Chichen Itza. The settlement of the Itza shall take place there. The quetzal shall come, the green bird shall come. Ah Kantenal shall come. It is the word of God. The Itza shall come.", a = "Mayan Tradition", b = "The Books of Chilam Balam" },
    { q = "Why man, he doth bestride the narrow world like a colossus; and we petty men walk under his huge legs, and peep about to find ourselves dishonorable graves.", a = "William Shakespeare", b = "Julius Caesar" },
    { q = "Come to me, all who labor and are heavy burdened, and I will give you rest.", a = "The Bible", b = "Matthew 11:28" },
    { q = "We live only to discover beauty. All else is a form of waiting.", a = "Kahlil Gibran", b = "Sand and Foam" },
    { q = "Most of us can, as we choose, make of this world either a palace or a prison.", a = "John Lubbock", b = "The Use of Life" },
    { q = "Libraries are as the shrine where all the relics of the ancient saints, full of true virtue, and all that without delusion or imposture are preserved and reposed.", a = "Sir Francis Bacon", b = "The Advancement of Learning" },
    { q = "They that go down to the sea in ships, that do business in great waters; these see the works of the Lord, and his wonders in the deep.", a = "The Bible", b = "Psalms 107:23-24" },
    { q = "The art of war teaches us to rely not on the likelihood of the enemy’s… not attacking, but rather on the fact that we have made our position unassailable.", a = "Sun Tzu", b = "The Art of War" },
    { q = "For it soars to a height to match the sky, and as if surging up from amongst the other buildings it stands on high and looks down upon the remainder of the city, adorning it, because it is a part of it, but glorying in its own beauty.", a = "Procopius", b = "De Aedificis" },
    { q = "I think that if ever a mortal heard the word of God it would be in a garden at the cool of the day.", a = "F. Frankfort Moore", b = "The Jessamy Bride" },
    { q = "Bushido is realized in the presence of death. This means choosing death whenever there is a choice between life and death. There is no other reasoning.", a = "Yamamoto Tsunetomo", b = "Hagakure" },
    { q = "The Law is a fortress on a hill that armies cannot take or floods wash away.", a = "Prophet Muhammad", b = "Hadith / Attributed" },
    { q = "Every genuine work of art has as much reason for being as the earth and the sun.", a = "Ralph Waldo Emerson", b = "Thoughts on Art" },
    { q = "Few romances can ever surpass that of the granite citadel on top of the beetling precipices of Machu Picchu, the crown of Inca Land.", a = "Hiram Bingham", b = "Inca Land" },
    { q = "Architecture has recorded the great ideas of the human race. Not only every religious symbol, but every human thought has its page in that vast book.", a = "Victor Hugo", b = "The Hunchback of Notre-Dame" },
    { q = "The ancient Oracle said that I was the wisest of all the Greeks. It is because I alone, of all the Greeks, know that I know nothing.", a = "Socrates", b = "Plato, Apology" },
    { q = "In preparing for battle I have always found that plans are useless, but planning is indispensible.", a = "Dwight D. Eisenhower", b = "Speech to National Defense Executive Reserve (1957)" },
    { q = "Things always seem fairer when we look back at them, and it is out of that inaccessible tower of the past that Longing leans and beckons.", a = "James Russell Lowell", b = "My Study Windows" },
    { q = "O, let not the pains of death which come upon thee enter into my body. I am the god Tem, and I am in the foremost part of the sky, and the power which protecteth me is that which is with all the gods forever.", a = "Ancient Egyptian (tr. E. A. Wallis Budge)", b = "The Book of the Dead" },
    { q = "I live and love in God’s peculiar light.", a = "Michelangelo Buonarroti", b = "Sonnets" },
    { q = "Give me your tired, your poor, / Your huddled masses yearning to breathe free, / The wretched refuse of your teeming shore. / Send these, the homeless, tempest-tossed to me, / I lift my lamp beside the golden door!", a = "Emma Lazarus", b = "The New Colossus" },
    { q = "Time crumbles things; everything grows old and is forgotten under the power of time.", a = "Aristotle", b = "Physics" },
    { q = "Those who lose dreaming are lost.", a = "Australian Aboriginal Proverb", b = "Traditional Saying" },
    { q = "The Taj Mahal rises above the banks of the river like a solitary tear suspended on the cheek of time.", a = "Rabindranath Tagore", b = "Lover's Gift and Crossing" },
    { q = "More than ever before in human history, we share a common destiny. We can master it only if we face it together. And that is why we have the United Nations.", a = "Kofi Annan", b = "Address to UN General Assembly" },
